files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #e0e0e0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background-image: repeating-linear-gradient(45deg, #16213e 0px, #16213e 2px, #1a1a2e 2px, #1a1a2e 8px);
}

.game-card {
  background: #0f3460;
  border: 4px solid #e94560;
  border-radius: 0;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 #e94560;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  color: #e94560;
  text-transform: uppercase;
  letter-spacing: 2px;
}

.subtitle {
  font-size: 1rem;
  margin-bottom: 24px;
  color: #a8b2d1;
}

.input-group {
  margin-bottom: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
}

label {
  font-weight: 600;
  color: #e0e0e0;
}

input[type="number"] {
  font-size: 1.25rem;
  padding: 10px 12px;
  width: 120px;
  text-align: center;
  border: 3px solid #e94560;
  background: #1a1a2e;
  color: #e0e0e0;
  border-radius: 0;
  font-family: inherit;
}

input[type="number"]:focus {
  outline: 3px solid #f5a623;
  outline-offset: 2px;
}

button {
  font-size: 1.125rem;
  font-family: inherit;
  padding: 10px 24px;
  margin: 4px;
  border: 3px solid #e94560;
  background: #e94560;
  color: #fff;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-weight: 700;
  border-radius: 0;
  transition: background 0.1s, transform 0.1s;
}

button:hover {
  background: #f5a623;
  border-color: #f5a623;
  color: #1a1a2e;
}

button:focus-visible {
  outline: 3px solid #f5a623;
  outline-offset: 2px;
}

button:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

#new-game-btn {
  background: #0f3460;
  color: #e0e0e0;
}

#new-game-btn:hover {
  background: #f5a623;
  color: #1a1a2e;
}

.feedback {
  font-size: 1.125rem;
  min-height: 2rem;
  margin-top: 16px;
  font-weight: 600;
  color: #f5a623;
}

.guess-count {
  margin-top: 12px;
  font-size: 1rem;
  color: #a8b2d1;
}

@media (max-width: 400px) {
  .game-card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  button {
    font-size: 1rem;
    padding: 8px 16px;
  }
}

let targetNumber;
let guessCount;
let gameOver;

const guessInput = document.getElementById('guess-input');
const guessBtn = document.getElementById('guess-btn');
const newGameBtn = document.getElementById('new-game-btn');
const feedback = document.getElementById('feedback');
const guessCountDisplay = document.getElementById('guess-count');

function startNewGame() {
  targetNumber = Math.floor(Math.random() * 100) + 1;
  guessCount = 0;
  gameOver = false;
  guessInput.value = '';
  guessInput.disabled = false;
  guessBtn.disabled = false;
  feedback.textContent = '';
  guessCountDisplay.textContent = '0';
  guessInput.focus();
}

function handleGuess() {
  if (gameOver) return;
  const value = parseInt(guessInput.value, 10);
  if (isNaN(value) || value < 1 || value > 100) {
    feedback.textContent = 'Please enter a number between 1 and 100.';
    return;
  }
  guessCount++;
  guessCountDisplay.textContent = guessCount;
  if (value === targetNumber) {
    feedback.textContent = 'Correct!';
    gameOver = true;
    guessInput.disabled = true;
    guessBtn.disabled = true;
  } else if (value > targetNumber) {
    feedback.textContent = 'Too high';
  } else {
    feedback.textContent = 'Too low';
  }
  guessInput.value = '';
  guessInput.focus();
}

guessBtn.addEventListener('click', handleGuess);
newGameBtn.addEventListener('click', startNewGame);
guessInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    handleGuess();
  }
});

startNewGame();
